  var ids=new ArrayList<String>();ids.add("terraformer");Terraformer.DEFINITIONS.keySet().forEach(s->ids.add("terraform_focus_"+s));for(String id:ids){jobs.add(d.save(c,"assets/witchinggadgets/blockstates/"+id+".json",map("variants",map("",map("model","witchinggadgets:block/"+id)))));jobs.add(d.save(c,"assets/witchinggadgets/models/block/"+id+".json",map("textures",map("particle","thaumcraft:block/metalbase"))));jobs.add(d.save(c,"assets/witchinggadgets/models/item/"+id+".json",map("parent","builtin/entity","textures",map("particle","thaumcraft:block/metalbase"),"display",map("gui",map("rotation",List.of(30,225,0),"scale",List.of(.625,.625,.625)),"ground",map("translation",List.of(0,3,0),"scale",List.of(.25,.25,.25)),"fixed",map("scale",List.of(.5,.5,.5)),"thirdperson_righthand",map("rotation",List.of(75,45,0),"translation",List.of(0,2.5,0),"scale",List.of(.375,.375,.375)),"firstperson_righthand",map("rotation",List.of(0,45,0),"scale",List.of(.4,.4,.4))))));jobs.add(d.save(c,"data/witchinggadgets/loot_tables/blocks/"+id+".json",map("type","minecraft:block","pools",List.of(map("rolls",1,"entries",List.of(map("type","minecraft:item","name","witchinggadgets:"+id)))))));}
  d.infusion(c,jobs,"terraformer","TERRAFORMER","witchinggadgets:terraformer","thaumcraft:alchemical_construct",3,Map.of("ordo",16,"permutatio",8,"terra",16),List.of("thaumcraft:balanced_shard","minecraft:iron_ingot","thaumcraft:essentia_tube","thaumcraft:silverwood_sapling","thaumcraft:essentia_tube","minecraft:iron_ingot"));
